package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.BackchannelClientNotificationEndpointVO;

class BackchannelClientNotificationEndpointValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of backchannel client notification endpoint of oauth client")
  void test_backchannel_client_notification_endpoint_value_holder_assign_plain_value() {
    Object holder = new Object();
    BackchannelClientNotificationEndpointValueHolder<Object> value =
        new BackchannelClientNotificationEndpointValueHolder<>(holder);
    Assertions.assertSame(holder, value.backchannelClientNotificationEndpoint("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getBackchannelClientNotificationEndpointValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getBackchannelClientNotificationEndpoint().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.backchannelClientNotificationEndpointNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getBackchannelClientNotificationEndpointValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getBackchannelClientNotificationEndpoint().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of backchannel client notification endpoint of oauth client")
  void test_backchannel_client_notification_endpoint_value_holder_assign_value_object() {
    Object holder = new Object();
    BackchannelClientNotificationEndpointValueHolder<Object> value =
        new BackchannelClientNotificationEndpointValueHolder<>(holder);
    BackchannelClientNotificationEndpointVO vo =
        BackchannelClientNotificationEndpointVO.from("one");
    Assertions.assertFalse(value.getBackchannelClientNotificationEndpointValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.backchannelClientNotificationEndpoint(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getBackchannelClientNotificationEndpointValue().orElseThrow());
    Assertions.assertSame(holder, value.backchannelClientNotificationEndpoint(Optional.empty()));
    Assertions.assertFalse(value.getBackchannelClientNotificationEndpointValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.backchannelClientNotificationEndpoint(Optional.of(vo)));
    Assertions.assertSame(vo, value.getBackchannelClientNotificationEndpointValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of backchannel client notification endpoint of oauth client against the original")
  void test_backchannel_client_notification_endpoint_value_holder_read() {
    Object holder = new Object();
    BackchannelClientNotificationEndpointValueHolder<Object> value =
        new BackchannelClientNotificationEndpointValueHolder<>(holder);
    BackchannelClientNotificationEndpointVO vo =
        BackchannelClientNotificationEndpointVO.from("one");
    BackchannelClientNotificationEndpointVO other =
        BackchannelClientNotificationEndpointVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getBackchannelClientNotificationEndpointValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other,
        value.readBackchannelClientNotificationEndpoint(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(
        value.readBackchannelClientNotificationEndpoint(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.backchannelClientNotificationEndpoint(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo,
        value.readBackchannelClientNotificationEndpoint(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo,
        value.readBackchannelClientNotificationEndpoint(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of backchannel client notification endpoint of oauth client")
  void test_backchannel_client_notification_endpoint_value_holder_unset() {
    Object holder = new Object();
    BackchannelClientNotificationEndpointValueHolder<Object> value =
        new BackchannelClientNotificationEndpointValueHolder<>(holder);
    BackchannelClientNotificationEndpointVO vo =
        BackchannelClientNotificationEndpointVO.from("one");
    value.backchannelClientNotificationEndpoint(vo);
    Assertions.assertSame(holder, value.unsetBackchannelClientNotificationEndpointIfMatches(
        "backchannelClientNotificationEndpoint_other"));
    Assertions.assertTrue(value.getBackchannelClientNotificationEndpointValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetBackchannelClientNotificationEndpointIfMatches(
        "backchannelClientNotificationEndpoint"));
    Assertions.assertFalse(value.getBackchannelClientNotificationEndpointValue().isPresent(),
        "The field name must clear the value");
    value.backchannelClientNotificationEndpoint(vo);
    Assertions.assertSame(holder, value.unsetBackchannelClientNotificationEndpoint());
    Assertions.assertFalse(value.getBackchannelClientNotificationEndpointValue().isPresent(),
        "Unset must clear the value");
  }
}
